# -*- coding: utf-8 -*-
"""Lecture 31 vignette pool B -- Pericardial Disease: constrictive pericarditis and
pericardial effusion.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Kussmaul sign and pericardial knock are the constriction findings keyed; pulsus
paradoxus is never used to separate constriction (s44 conflict, scope docstring).
Named findings carry their description in parentheses.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l31_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


CON = "Constrictive pericarditis"
EFF = "Pericardial effusion"
